{
  "discovery": [
    {
      "rpc": "Exec",
      "args": {
        "path": "/bin/sql",
        "stdin": "WITH candidate_skus AS (\n  SELECT product_sku, record_path, product_family_id\n  FROM product_variants\n  WHERE brand = 'Heco' AND product_name LIKE '%3DW-64B%' AND product_name LIKE '%Nut Bolt and Washer%'\n  UNION\n  SELECT pv.product_sku, pv.record_path, pv.product_family_id\n  FROM product_families pf\n  JOIN product_variants pv ON pv.product_family_id = pf.product_family_id\n  WHERE pf.brand = 'Heco' AND pf.product_family_name LIKE '%3DW-64B%' AND pf.product_family_name LIKE '%Nut Bolt and Washer%'\n)\nSELECT cs.product_sku, cs.record_path,\n       MAX(CASE WHEN pvp.property_key = 'fastener_type' THEN pvp.property_value_text END) AS fastener_type,\n       MAX(CASE WHEN pvp.property_key = 'diameter' THEN pvp.property_value_text END) AS diameter\nFROM candidate_skus cs\nLEFT JOIN product_variant_properties pvp ON cs.product_sku = pvp.product_sku\nGROUP BY cs.product_sku, cs.record_path\nLIMIT 1;"
      },
      "bind": "product_info_raw"
    }
  ],
  "rowsets": [],
  "compute": [
    {
      "prim": "first",
      "args": ["$product_info_raw"],
      "into": "product_row"
    },
    {
      "prim": "get",
      "args": ["$product_row", "product_sku"],
      "into": "product_sku"
    },
    {
      "prim": "get",
      "args": ["$product_row", "record_path"],
      "into": "product_variant.record_path"
    },
    {
      "prim": "get",
      "args": ["$product_row", "fastener_type"],
      "into": "properties.fastener_type"
    },
    {
      "prim": "get",
      "args": ["$product_row", "diameter"],
      "into": "properties.diameter"
    }
  ],
  "decision": {
    "branches": [
      {
        "when": {
          "op": "isnull",
          "lhs": "$product_sku",
          "rhs": null
        },
        "label": "unsupported"
      },
      {
        "when": {
          "op": "and",
          "args": [
            {
              "op": "in_set",
              "lhs": "$properties.fastener_type",
              "rhs": ["bolt"]
            },
            {
              "op": "in_set",
              "lhs": "$properties.diameter",
              "rhs": ["10 mm"]
            },
            {
              "op": "in_set",
              "lhs": "$properties.diameter",
              "rhs": ["8 mm"]
            }
          ]
        },
        "label": "ok"
      }
    ],
    "default_label": "unsupported"
  },
  "ops": [],
  "answer": {
    "ok": {
      "message": "Product record: {product_variant.record_path} (SKU: {product_sku}). Claim verification: verified",
      "outcome": "OUTCOME_OK",
      "refs": []
    },
    "unsupported": {
      "message": "Product record: {product_variant.record_path} (SKU: {product_sku}). Claim verification: not verified",
      "outcome": "OUTCOME_NONE_UNSUPPORTED",
      "refs": []
    }
  },
  "custom_extract": []
}

